[asy]
draw(Circle((0,0),10));
draw((0,0)--(8.7,-5));
draw((0,0)--(-8.7,-5));
draw((0,0)--(0,10));
label("1",(7,7),SW);
label("3",(-7,7),SE);
label("2",(0,-2),S);
draw((0,0)--(3,5),Arrow);
